    "guide_3": "4d6dl1 \u099a\u09be\u09b0\u099f\u09bf d6 \u09b0\u09cb\u09b2 \u0995\u09b0\u09c7 \u09b8\u09ac\u099a\u09c7\u09af\u09bc\u09c7 \u099b\u09cb\u099f\u099f\u09bf \u09ac\u09be\u09a6 \u09a6\u09c7\u09af\u09bc \u2014 \u09a1\u09bf\u0985\u09cd\u09af\u09be\u09a8\u09cd\u09a1\u09a1\u09bf \u0985\u09cd\u09af\u09be\u09ac\u09bf\u09b2\u09bf\u099f\u09bf \u09b8\u09cd\u0995\u09cb\u09b0 \u09b0\u09cb\u09b2\u09c7\u09b0 \u0995\u09cd\u09b2\u09be\u09b8\u09bf\u0995 \u0989\u09aa\u09be\u09af\u09bc\u0964",
    "guide_4": "2d20kh1 \u09a6\u09c1\u099f\u09bf d20 \u09b0\u09cb\u09b2 \u0995\u09b0\u09c7 \u09ac\u09a1\u09bc\u099f\u09bf \u09b0\u09be\u0996\u09c7 \u2014 \u098f\u099f\u09be\u0987 \u0985\u09cd\u09af\u09be\u09a1\u09ad\u09be\u09a8\u09cd\u099f\u09c7\u099c\u0964 2d20kl1 \u099b\u09cb\u099f\u099f\u09bf \u09b0\u09be\u0996\u09c7 \u2014 \u09a1\u09bf\u09b8\u0985\u09cd\u09af\u09be\u09a1\u09ad\u09be\u09a8\u09cd\u099f\u09c7\u099c\u0964",
    "guide_5": "d% \u09b9\u09b2\u09cb \u09aa\u09be\u09b0\u09cd\u09b8\u09c7\u09a8\u09cd\u099f\u09be\u0987\u09b2 \u09a1\u09be\u0987\u09b8: \u098f\u0995\u099f\u09bf d100, \u09e7-\u09e7\u09e6\u09e6 \u09b9\u09bf\u09b8\u09c7\u09ac\u09c7 \u09aa\u09a1\u09bc\u09be \u09b9\u09af\u09bc\u0964",
    "guide_6": "\u098f\u0995\u099f\u09bf\u09ae\u09be\u09a4\u09cd\u09b0 d20-\u09a4\u09c7 \u09a8\u09cd\u09af\u09be\u099a\u09be\u09b0\u09be\u09b2 \u09e8\u09e6 \u0995\u09cd\u09b0\u09bf\u099f\u09bf\u0995\u09cd\u09af\u09be\u09b2 \u09b9\u09bf\u099f; \u09a8\u09cd\u09af\u09be\u099a\u09be\u09b0\u09be\u09b2 \u09e7 \u0995\u09cd\u09b0\u09bf\u099f\u09bf\u0995\u09cd\u09af\u09be\u09b2 \u09ab\u09c7\u0987\u09b2\u0964",
    "guide_7": "\u09b0\u09cb\u09b2\u0997\u09c1\u09b2\u09cb \u0986\u09aa\u09a8\u09be\u09b0 \u09a1\u09bf\u09ad\u09be\u0987\u09b8\u09c7\u09b0 \u09ac\u09bf\u09b2\u09cd\u099f-\u0987\u09a8 \u09b0\u200d\u09cd\u09af\u09be\u09a8\u09cd\u09a1\u09ae \u09b8\u0982\u0996\u09cd\u09af\u09be (Math.random) \u09ac\u09cd\u09af\u09ac\u09b9\u09be\u09b0 \u0995\u09b0\u09c7\u0964 \u0997\u09c7\u09ae\u09c7\u09b0 \u099c\u09a8\u09cd\u09af \u09af\u09a5\u09c7\u09b7\u09cd\u099f \u09b0\u200d\u09cd\u09af\u09be\u09a8\u09cd\u09a1\u09ae, \u0995\u09cd\u09b0\u09bf\u09aa\u09cd\u099f\u09cb\u0997\u09cd\u09b0\u09be\u09ab\u09bf \u09ac\u09be \u099c\u09c1\u09af\u09bc\u09be\u09b0 \u099c\u09a8\u09cd\u09af \u09a8\u09af\u09bc\u0964",
